<script setup lang="ts">
import { computed, ref } from 'vue'
import { useData, useRoute, withBase } from 'vitepress'
const route=useRoute();const {isDark}=useData();const menuOpen=ref(false);const siteBase=withBase('/');const relativePath=computed(()=>{const path=route.path.replace(/index\.html$/,'');return path.startsWith(siteBase)?`/${path.slice(siteBase.length)}`:path});const chinese=computed(()=>relativePath.value==='/zh/'||relativePath.value.startsWith('/zh/'));const normalizedPath=computed(()=>relativePath.value.endsWith('/')?relativePath.value:`${relativePath.value}/`);const homeLikePaths=['/','/zh/','/en/','/zh/preview/research-center-home/','/en/preview/research-center-home/'];const visible=computed(()=>!homeLikePaths.includes(normalizedPath.value));const label=computed(()=>chinese.value?'返回':'Back');const zhPath=computed(()=>{const p=normalizedPath.value;if(p==='/'||p==='/en/')return withBase('/zh/');if(p.startsWith('/en/'))return withBase(`/zh/${p.slice(4)}`);if(p.startsWith('/zh/'))return withBase(p);return withBase('/zh/')});const enPath=computed(()=>{const p=normalizedPath.value;if(p==='/'||p==='/en/'||p==='/zh/')return withBase('/');if(p.startsWith('/zh/'))return withBase(`/en/${p.slice(4)}`);if(p.startsWith('/en/'))return withBase(p);return withBase('/')});function goBack(){if(typeof window==='undefined')return;if(window.history.length>1)window.history.back();else window.location.assign(withBase(chinese.value?'/zh/':'/'))}function toggleAppearance(){isDark.value=!isDark.value}function toggleMenu(){menuOpen.value=!menuOpen.value}
</script>
<template>
  <button class="mobile-menu-trigger" type="button" :aria-expanded="menuOpen" @click="toggleMenu"><span aria-hidden="true">☰</span><b>{{chinese?'设置':'Settings'}}</b></button>
  <div v-if="visible" class="mobile-action-bar"><button class="mobile-back" type="button" @click="goBack"><span aria-hidden="true">←</span><b>{{label}}</b></button></div>
  <nav class="global-controls" :class="{open:menuOpen}" :aria-label="chinese?'语言与外观':'Language and appearance'">
    <div class="control-row"><span>{{chinese?'语言':'Language'}}</span><div class="global-language"><strong v-if="chinese">中文</strong><a v-else :href="zhPath">中文</a><strong v-if="!chinese">EN</strong><a v-else :href="enPath">EN</a></div></div>
    <div class="control-row"><span>{{chinese?'外观':'Appearance'}}</span><button class="global-appearance" type="button" @click="toggleAppearance">{{isDark?(chinese?'暗色':'Dark'):(chinese?'明亮':'Light')}}</button></div>
  </nav>
  <button v-if="visible" class="global-back" type="button" @click="goBack"><span aria-hidden="true">←</span><span>{{chinese?'返回上一页':'Back'}}</span></button>
</template>
